import random

def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    my = [h[0] for h in history]
    op = [h[1] for h in history]

    # Count outcomes
    cc = cd = dc = dd = 0
    for a, b in history:
        if a == 'C' and b == 'C':
            cc += 1
        elif a == 'C' and b == 'D':
            cd += 1
        elif a == 'D' and b == 'C':
            dc += 1
        else:
            dd += 1

    # Immediate retaliation against last defection
    if op[-1] == 'D' and my[-1] == 'C':
        return 'D'

    # Forgiving after mutual defection: probe cooperation occasionally
    if my[-1] == 'D' and op[-1] == 'D':
        if n < 90 and rng.random() < 0.15:
            return 'C'
        return 'D'

    # Exploit persistent defectors
    recent = history[-8:] if n >= 8 else history
    op_def = sum(1 for _, b in recent if b == 'D')
    if len(recent) > 0 and op_def >= len(recent) - 1 and n >= 6:
        return 'D'

    # Default: cooperate, but sometimes test
    if n < 95 and rng.random() < 0.04:
        return 'D'
    return 'C'
